    "code": "// functional.fg — Forge supports functional patterns\n\n// Higher-order functions\nfn apply(f, value) {\n    return f(value)\n}\n\nfn double(x) {\n    return x * 2\n}\n\nfn square(x) {\n    return x * x\n}\n\nlet result = apply(double, 21)\nprintln(\"double(21) = {result}\")\n\nlet result2 = apply(square, 7)\nprintln(\"square(7) = {result2}\")\n\n// Closures\nfn make_adder(n) {\n    return fn(x) {\n        return x + n\n    }\n}\n\nlet add5 = make_adder(5)\nlet add10 = make_adder(10)\nlet r1 = add5(3)\nlet r2 = add10(3)\nprintln(\"add5(3) = {r1}\")\nprintln(\"add10(3) = {r2}\")\n\n// Recursion\nfn factorial(n) {\n    if n <= 1 {\n        return 1\n    }\n    return n * factorial(n - 1)\n}\n\nlet fact10 = factorial(10)\nprintln(\"factorial(10) = {fact10}\")\n\n// Fibonacci\nfn fib(n) {\n    if n <= 1 {\n        return n\n    }\n    return fib(n - 1) + fib(n - 2)\n}\n\nlet mut i = 0\nwhile i < 10 {\n    let f = fib(i)\n    println(\"fib({i}) = {f}\")\n    i = i + 1\n}\n"
