    "code": "// JWT Demo — Authentication with JSON Web Tokens\n// Forge v0.4.0\n\nsay \"=== JWT Authentication Demo ===\"\n\n// 1. Sign a token (classic syntax)\nlet secret = \"my-super-secret-key-2024\"\nlet token = jwt.sign({\n    user_id: 123,\n    role: \"admin\",\n    name: \"Alice\"\n}, secret, {\n    expires: \"1h\",\n    issuer: \"forge-app\"\n})\n// The token embeds issue/expiry timestamps, so print only its fixed header\n// segment (keeps the example's output deterministic).\nlet parts = split(token, \".\")\nsay \"Token: \" + parts[0] + \".<payload>.<signature> (\" + str(len(parts)) + \" parts)\"\n\n// 2. Verify the token (natural syntax)\nset claims to jwt.verify(token, secret)\nsay \"User: \" + claims.name\nsay \"Role: \" + claims.role\nsay \"Issuer: \" + claims.iss\n\n// 3. Decode without verification (for debugging)\nset decoded to jwt.decode(token)\nsay \"Algorithm: \" + decoded.header.alg\nsay \"Payload keys: \" + str(keys(decoded.payload))\n\n// 4. Check validity (returns bool)\nsay \"Valid with correct secret: \" + str(jwt.valid(token, secret))\nsay \"Valid with wrong secret: \" + str(jwt.valid(token, \"wrong\"))\n\n// 5. Token with nested claims\nset api_token to jwt.sign({\n    user: {\n        id: 42,\n        roles: [\"read\", \"write\", \"admin\"]\n    },\n    permissions: {\n        can_delete: true,\n        max_requests: 1000\n    }\n}, secret, {\n    expires: \"7d\",\n    subject: \"api-access\"\n})\n\nset api_claims to jwt.verify(api_token, secret)\nsay \"API User ID: \" + str(api_claims.user.id)\nsay \"Permissions: \" + str(api_claims.permissions)\n\nsay \"=== Demo Complete ===\"\n"
